class FullscreenButton extends HTMLElement{constructor(){super(),this.attachShadow({mode:"open"})}connectedCallback(){this.shadowRoot.innerHTML='\n        <style>\n          @import url(\'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css\');\n\n          .fullscreen-control {\n            position: fixed;\n            top: 10px;\n            right: 10px;\n            cursor: pointer;\n            font-size: 20px;\n            width: 48px;\n            height: 48px;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            z-index: 9999;\n            color: white;\n            background: rgba(20, 20, 24, 0.16);\n            backdrop-filter: blur(2px) saturate(165%);\n            -webkit-backdrop-filter: blur(2px) saturate(165%);\n            border: 1px solid rgba(255, 255, 255, 0.28);\n            border-radius: 50%;\n            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.3);\n            transition: background 0.2s ease;\n          }\n          .fullscreen-control:hover {\n            background: rgba(20, 20, 24, 0.3);\n          }\n            @media (max-width: 768px) {\n                :host {\n                    display: none\n                }\n            }\n        </style>\n        <i id="fullscreen-control" class="fas fa-expand fullscreen-control"></i>\n      ',this.initFullscreenControl()}initFullscreenControl(){const e=this.shadowRoot.getElementById("fullscreen-control");let n=!1;e.addEventListener("click",(()=>{n?(document.exitFullscreen?document.exitFullscreen():document.mozCancelFullScreen?document.mozCancelFullScreen():document.webkitExitFullscreen?document.webkitExitFullscreen():document.msExitFullscreen&&document.msExitFullscreen(),e.classList.add("fa-expand"),e.classList.remove("fa-compress")):(document.documentElement.requestFullscreen?document.documentElement.requestFullscreen():document.documentElement.mozRequestFullScreen?document.documentElement.mozRequestFullScreen():document.documentElement.webkitRequestFullscreen?document.documentElement.webkitRequestFullscreen():document.documentElement.msRequestFullscreen&&document.documentElement.msRequestFullscreen(),e.classList.add("fa-compress"),e.classList.remove("fa-expand")),n=!n}))}}customElements.define("fullscreen-button",FullscreenButton);